from src.nodes.base import BaseNode
from src.runtime.assets.acquisition import (
    get_fab_library_scanner, get_megascans_scanner, get_library_index
)
import json

class Hou_Mcp_Library_Scan(BaseNode):
    name = "hou_mcp_library_scan"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("source",       "string", widget_type="text", default="all")
        self.add_input("library_path", "string", widget_type="text", default="")
        # [AUTO-GENERATED-PORTS-END]
        self.add_output("scan_result_json", "string")
        self.add_output("asset_count",      "int")

    async def execute(self, inputs):
        source  = str(inputs.get("source",       "all") or "all").strip().lower()
        lpath   = str(inputs.get("library_path", "")   or "")
        idx     = get_library_index()
        combined_assets = []
        errors = []
        try:
            if source in ("fab", "all"):
                fab_result = get_fab_library_scanner().scan_library(lpath)
                for rec in fab_result.assets_found:
                    desc = get_fab_library_scanner().build_asset_descriptor(rec)
                    idx.add_from_descriptor(desc, provenance="fab_local_library")
                    combined_assets.append(rec.to_dict())
                if fab_result.errors:
                    errors.extend(fab_result.errors)
                self.log_info(f"Fab scan: {len(fab_result.assets_found)} asset(s) found.")
            if source in ("megascans", "all"):
                ms_result = get_megascans_scanner().scan_megascans(lpath)
                for rec in ms_result.assets_found:
                    desc = get_megascans_scanner().build_asset_descriptor(rec)
                    idx.add_from_descriptor(desc, provenance="megascans_local_library")
                    combined_assets.append(rec.to_dict())
                if ms_result.errors:
                    errors.extend(ms_result.errors)
                self.log_info(f"Megascans scan: {len(ms_result.assets_found)} asset(s) found.")
            result = {"source": source, "asset_count": len(combined_assets),
                      "assets": combined_assets, "errors": errors}
            return {"scan_result_json": json.dumps(result, sort_keys=True, default=str),
                    "asset_count": len(combined_assets), "exec_out": True}
        except Exception as exc:
            self.log_error(f"Library scan failed: {exc}")
            return {"scan_result_json": "{}", "asset_count": 0, "exec_out": True}

def register_node():
    return Hou_Mcp_Library_Scan
